const auditGates = (
  values: Array<[WealthAuditItem["gates"][number]["id"], string, string, string, string, number]>,
): WealthAuditItem["gates"] => values.map(([id, question, clearSign, dangerSign, nextAction, chapterId]) => ({
  id,
  label: ({ purpose: "Purpose", source: "Source", amount: "Amount", outlet: "Outlet", intention: "Intention" } as const)[id],
  question,
  clearSign,
  dangerSign,
  nextAction,
  chapterId,
}));

